import{_ as a,c as s,o,j as n,Y as r,t as i}from"./chunks/framework.BNTND4LZ.js";const g=JSON.parse('{"title":"ftpusers | x-cmd man (man5) | list of users that may not log in via the FTP daemon","titleTemplate":false,"description":"x-cmd man (man5 Manual Page) | ftpusers - list of users that may not log in via the FTP daemon","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"ftpusers | x-cmd man (man5) | list of users that may not log in via the FTP daemon"}],["meta",{"name":"og:description","content":"x-cmd man (man5 Manual Page) | ftpusers - list of users that may not log in via the FTP daemon"}]]},"headers":[],"params":{"isMan":true,"man":"ftpusers","category":"man5","desc":"list of users that may not log in via the FTP daemon"},"relativePath":"man5/ftpusers.md","filePath":"man5/[man].md"}'),l={name:"man5/ftpusers.md"},m={class:"visually-hidden"};function u(t,e,d,h,p,f){return o(),s("div",null,[n("h1",m,i(t.$params.man),1),e[0]||(e[0]=r('<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>ftpusers - list of users that may not log in via the FTP daemon</p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>The text file <strong>ftpusers</strong> contains a list of users that may not log in using the File Transfer Protocol (FTP) server daemon. This file is used not merely for system administration purposes but also for improving security within a TCP/IP networked environment.</p><p>The <strong>ftpusers</strong> file will typically contain a list of the users that either have no business using ftp or have too many privileges to be allowed to log in through the FTP server daemon. Such users usually include root, daemon, bin, uucp, and news.</p><p>If your FTP server daemon doesn&#39;t use <strong>ftpusers</strong>, then it is suggested that you read its documentation to find out how to block access for certain users. Washington University FTP server Daemon (wuftpd) and Professional FTP Daemon (proftpd) are known to make use of <strong>ftpusers</strong>.</p><h3 id="format" tabindex="-1">Format <a class="header-anchor" href="#format" aria-label="Permalink to &quot;Format&quot;">​</a></h3><p>The format of <strong>ftpusers</strong> is very simple. There is one account name (or username) per line. Lines starting with a # are ignored.</p><h2 id="files" tabindex="-1">FILES <a class="header-anchor" href="#files" aria-label="Permalink to &quot;FILES&quot;">​</a></h2><p><em>/etc/ftpusers</em></p><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>passwd</strong>(5), <strong>proftpd</strong>(8), <strong>wuftpd</strong>(8)</p>',12))])}const P=a(l,[["render",u]]);export{g as __pageData,P as default};
